import{_ as a,o as l,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"2018-11-20 Crimson/Seastar OSD Meeting","description":"","frontmatter":{"title":"2018-11-20 Crimson/Seastar OSD Meeting","date":"2018-11-20T00:00:00.000Z","updated":"2018-11-22T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH算法","高可用性","可伸缩性","对象存储","块存储","文件系统存储","一致性","去中心化","性能","Bluestore","Bluefs","Rocksdb","OSD","MON","MDS","PG","RADOS","librados","libcephfs","cephfs","rbd","radosgw","RGW","RESTful API","认证","授权","加密","纠删码","复制","快照","克隆","虚拟化","云计算","AWS","Azure","Google Cloud","混合云","多云","存储集群","监控","仪表板","管理","自动化","集成","容器化","Kubernetes","Docker","节点","磁盘","SSD","HDD","JBOD","SAN","NAS","网络","网络拓扑","失效域","恢复","弹性","负载均衡","缓存","压缩","去重","分层","性能调整","基准测试","测试","验证"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/2018-11-20_Crimson_Seastar_OSD_Meeting.md","filePath":"posts/2018/2018-11-20_Crimson_Seastar_OSD_Meeting.md","lastUpdated":1780460162000}'),r={name:"posts/2018/2018-11-20_Crimson_Seastar_OSD_Meeting.md"};function s(o,e,n,_,d,p){return l(),i("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2018年11月20日</p><p><strong>参会人员</strong>： Neha（主持人）、Mark、Casey、Emma、Free Duke等</p><p><strong>会议主题</strong>：</p><ul><li>Ceph存储集群的维护和优化</li><li>多连接支持与性能测试</li><li>缓冲区列表的优化</li><li>内存存储的测试与改进</li></ul><h3 id="关键细节与讨论议题" tabindex="-1">关键细节与讨论议题： <a class="header-anchor" href="#关键细节与讨论议题" aria-label="Permalink to &quot;关键细节与讨论议题：&quot;">​</a></h3><p><strong>1. Ceph存储集群维护与优化</strong></p><ul><li>Neha询问了Khmer Pilate项目的进展情况。</li><li>Mark分享了连接状态封装和协议优化的工作，Casey对此表示了关注。</li><li>Emma提到与RocksDB的新联系人交流，希望了解他们的设计并寻求合作。</li></ul><p><strong>2. 多连接支持与性能测试</strong></p><ul><li>Neha讨论了与RocksDB的合作可能性。</li><li>Mark分享了多连接实现的进展，并解释了使用纯IP进行连接分片的问题。</li><li>Emma提出了使用多个IP地址进行测试的建议。</li></ul><p><strong>3. 缓冲区列表的优化</strong></p><ul><li>Casey分享了缓冲区列表优化的工作，并讨论了针对单线程无锁设备的应用场景。</li><li>Emma提到将后续工作转向简化路径，以便在理解了复制副本的Red Hat情况后进行。</li></ul><p><strong>4. 内存存储的测试与改进</strong></p><ul><li>Neha讨论了在Münster中进行测试时遇到的锁问题，并提出了使用TSX进行优化的建议。</li><li>Emma表示将继续工作，翻译基于Red Oak的副本关键路径分析。</li></ul><h3 id="决定的事项" tabindex="-1">决定的事项： <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项：&quot;">​</a></h3><ul><li>继续推进Ceph存储集群的维护和优化工作。</li><li>完成多连接支持与性能测试，并解决使用纯IP进行连接分片的问题。</li><li>完成缓冲区列表的优化工作，并考虑简化路径。</li><li>继续改进内存存储的测试与改进工作。</li></ul><h3 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h3><ul><li>Neha将跟进Khmer Pilate的更新。</li><li>Mark将继续与Casey合作，优化连接状态封装和协议。</li><li>Emma将尝试使用多个IP地址进行测试，并与RocksDB团队进行交流。</li><li>Casey将继续优化缓冲区列表，并考虑简化路径。</li><li>Emma将继续工作，翻译基于Red Oak的副本关键路径分析。</li></ul>',18)])])}const m=a(r,[["render",s]]);export{h as __pageData,m as default};
